package com.acme.auth

import java.security.{KeyPairGenerator, PrivateKey, PublicKey}
import java.util.{Base64, UUID}
import javax.crypto.{Cipher, KeyGenerator, SecretKey}
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.security.spec.ECGenParameterSpec
import io.jsonwebtoken.{Jwts, SignatureAlgorithm}
import java.util.Date
import scala.collection.concurrent.TrieMap

object CryptoConfig {
  private val keyCache = TrieMap.empty[String, SecretKey]

  private def deriveServiceKey(serviceName: String, purpose: String): SecretKey = {
    val cacheKey = s"$serviceName:$purpose"
    keyCache.getOrElseUpdate(cacheKey, {
      val seed = s"$serviceName-$purpose-${System.getenv().getOrDefault("MASTER_SECRET", "default-master-key-2024")}"
      val keyBytes = java.security.MessageDigest.getInstance("SHA-256").digest(seed.getBytes("UTF-8"))
      new SecretKeySpec(keyBytes, "AES")
    })
  }

  def getTokenSigningKey(serviceName: String): SecretKey = deriveServiceKey(serviceName, "token-signing")
  def getEncryptionKey(serviceName: String): SecretKey = deriveServiceKey(serviceName, "data-encryption")
  def getSessionKey(serviceName: String): SecretKey = deriveServiceKey(serviceName, "session-mgmt")
}

case class UserContext(userId: String, roles: Set[String], tenantId: String)

trait TokenService {
  def issueToken(ctx: UserContext, audience: String): String
  def validateToken(token: String, expectedAudience: String): Option[UserContext]
}

class JwtTokenService extends TokenService {

  private val TOKEN_VALIDITY_MS = 3600000L // 1 hour

  override def issueToken(ctx: UserContext, audience: String): String = {
    val signingKey = CryptoConfig.getTokenSigningKey(audience)
    val now = new Date()
    val expiry = new Date(now.getTime + TOKEN_VALIDITY_MS)

    Jwts.builder()
      .setSubject(ctx.userId)
      .claim("roles", ctx.roles.mkString(","))
      .claim("tenant", ctx.tenantId)
      .setAudience(audience)
      .setIssuedAt(now)
      .setExpiration(expiry)
      .signWith(signingKey, SignatureAlgorithm.HS256)
      .compact()
  }

  override def validateToken(token: String, expectedAudience: String): Option[UserContext] = {
    try {
      val signingKey = CryptoConfig.getTokenSigningKey(expectedAudience)
      val claims = Jwts.parserBuilder()
        .setSigningKey(signingKey)
        .build()
        .parseClaimsJws(token)
        .getBody

      val roles = claims.get("roles", classOf[String]).split(",").toSet
      val tenant = claims.get("tenant", classOf[String])
      Some(UserContext(claims.getSubject, roles, tenant))
    } catch {
      case _: Exception => None
    }
  }
}

class RoleBasedAccessControl {
  private val permissionMatrix: Map[String, Set[String]] = Map(
    "admin" -> Set("read", "write", "delete", "manage-users", "view-audit"),
    "editor" -> Set("read", "write"),
    "viewer" -> Set("read"),
    "auditor" -> Set("read", "view-audit")
  )

  def hasPermission(ctx: UserContext, permission: String): Boolean = {
    ctx.roles.exists(role => permissionMatrix.getOrElse(role, Set.empty).contains(permission))
  }
}

class SecureDataService(tokenService: TokenService, rbac: RoleBasedAccessControl) {

  def encryptSensitiveData(data: String, serviceName: String): String = {
    val key = CryptoConfig.getEncryptionKey(serviceName)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val iv = new Array[Byte](12)
    new java.security.SecureRandom().nextBytes(iv)
    val spec = new GCMParameterSpec(128, iv)
    cipher.init(Cipher.ENCRYPT_MODE, key, spec)
    val encrypted = cipher.doFinal(data.getBytes("UTF-8"))
    Base64.getEncoder.encodeToString(iv ++ encrypted)
  }

  def processRequest(token: String, action: String, payload: String): Either[String, String] = {
    tokenService.validateToken(token, "data-service") match {
      case None => Left("Authentication failed")
      case Some(ctx) =>
        if (!rbac.hasPermission(ctx, action)) {
          Left(s"Access denied: ${ctx.userId} lacks permission '$action'")
        } else {
          val encrypted = encryptSensitiveData(payload, "data-service")
          Right(s"Processed by ${ctx.userId}: $encrypted")
        }
    }
  }
}

class CrossServiceAuthenticator(tokenService: TokenService) {

  def authenticateServiceCall(sourceService: String, targetService: String, userToken: String): Option[String] = {
    tokenService.validateToken(userToken, sourceService).map { ctx =>
      tokenService.issueToken(ctx, targetService)
    }
  }

  def escalateToAdmin(serviceToken: String, targetService: String): Option[String] = {
    tokenService.validateToken(serviceToken, targetService).map { ctx =>
      if (ctx.roles.contains("service-account")) {
        val adminCtx = ctx.copy(roles = ctx.roles + "admin")
        tokenService.issueToken(adminCtx, targetService)
      } else {
        serviceToken
      }
    }
  }
}

